mapper.select:
select a.id, a.cid, a.uid, a.field_id, a.field, a.task_id, a.address, a.value, a.grade, a.indicator
    , a.status, a.reason, a.collect_time, a.create_time, a.device_name, a.device_sn, a.field_name
from iot_collect_data a


        and a.uid=#{entity.uid}


        and a.cid=#{entity.cid}


        and a.device_sn=#{entity.deviceSn}


        and a.collect_mode = #{entity.collectMode}


        and a.product_code=#{entity.productCode}


        and a.field_id=#{entity.fieldId}


        and a.task_id=#{entity.taskId}


        and a.status=#{entity.status}



            and UNIX_TIMESTAMP(a.collect_time) * 1000 between #{entity.startTimestamp} and #{entity.endTimestamp}


            and UNIX_TIMESTAMP(a.collect_time) * 1000 >= #{entity.startTimestamp}


            and #{entity.endTimestamp} >= UNIX_TIMESTAMP(a.collect_time) * 1000



order by a.collect_time desc


    select count(1) value, field,


    select avg(value) value, field,


    select max(value) value, field,


    select min(value) value, field,


    date_format(collect_time, '%Y') category


    date_format(collect_time, '%Y-%m') category


    date_format(collect_time, '%Y-%m-%d') category


    date_format(collect_time, '%y-%m-%d %H') category

from iot_collect_data


        and uid=#{uid}


        and product_code=#{productCode}


        and (
        field = #{field}
    )

    and UNIX_TIMESTAMP(collect_time) * 1000 between #{startTimestamp} and #{endTimestamp}

group by category,field

select * from iot_collect_data


        and uid=#{uid}


        and product_code=#{productCode}


        and (
        field = #{field}
    )

    and UNIX_TIMESTAMP(collect_time) * 1000 between #{startTimestamp} and #{endTimestamp}

select * from iot_collect_data


        and uid=#{uid}


        and product_code=#{productCode}


        and (
        field = #{field}
    )

    and UNIX_TIMESTAMP(collect_time) * 1000 between #{startTimestamp} and #{endTimestamp}

select a.cid, a.uid, a.task_id, group_concat(concat(a.field, '=', if(a.status, a.value, a.reason)) separator ':::') value
    , a.status, a.reason, a.collect_time, a.create_time, a.device_name, a.device_sn
from iot_collect_data a


        and a.uid=#{entity.uid}


        and a.device_sn=#{entity.deviceSn}


        and a.collect_mode = #{entity.collectMode}


        and a.device_group_id=#{entity.deviceGroupId}


        and a.product_code=#{entity.productCode}


        and a.task_id=#{entity.taskId}



            and UNIX_TIMESTAMP(a.collect_time) * 1000 between #{entity.startTimestamp} and #{entity.endTimestamp}


            and UNIX_TIMESTAMP(a.collect_time) * 1000 >= #{entity.startTimestamp}


            and #{entity.endTimestamp} >= UNIX_TIMESTAMP(a.collect_time) * 1000



group by a.cid, a.uid order by a.collect_time desc

select.if:
select ifnull(value, 0) value, field, b.name category from (

        select count(1) value, field, product_code


        select sum(value) value, field, product_code


        select avg(value) value, field, product_code


        select max(value) value, field, product_code


        select min(value) value, field, product_code

    from iot_collect_data
    where field = #{field} and (UNIX_TIMESTAMP(collect_time) * 1000 between #{startTime} and #{endTime}) and product_code in (

            #{productCode}

    )
) as a right join iot_product b on a.product_code = b.code
where b.code in (

        #{productCode}

)
group by b.code

select ifnull(value, 0) value, field, b.name category from (

        select count(1) value, field, uid


        select sum(value) value, field, uid


        select avg(value) value, field, uid


        select max(value) value, field, uid


        select min(value) value, field, uid

    from iot_collect_data
    where product_code=#{productCode} and field = #{field} and (UNIX_TIMESTAMP(collect_time) * 1000 between #{startTime} and #{endTime}) and uid in (

        #{uid}

    )
) as a
right join iot_device b on b.uid=a.uid
where b.uid in (

        #{uid}

)
group by b.uid

select ifnull(value, 0) value, field, b.name category from (

        select count(1) value, field, device_group_id


        select sum(value) value, field, device_group_id


        select avg(value) value, field, device_group_id


        select max(value) value, field, device_group_id


        select min(value) value, field, device_group_id

    from iot_collect_data
    where product_code=#{productCode} and field = #{field} and (UNIX_TIMESTAMP(collect_time) * 1000 between #{startTime} and #{endTime}) and device_group_id in (

            #{groupId}

    )
) as a
right join iot_device_group b on b.id=a.device_group_id
where b.id in (

        #{groupId}

)
group by b.id

mapper.select:
SELECT MAX(value + 0) AS `max`, MIN(value + 0) AS `min`,
       AVG(value + 0) AS `avg`, COUNT(*)       AS `count`,
       (SELECT collect_time
        FROM iot_collect_data
        WHERE uid = #{uid}
          AND collect_time BETWEEN #{start} AND #{end}
          AND value IS NOT NULL AND field_id = #{fieldId} AND status = 1
        ORDER BY value + 0 DESC LIMIT 1)      AS `maxTime`,
       (SELECT collect_time
        FROM iot_collect_data
        WHERE uid = #{uid}
          AND collect_time BETWEEN #{start} AND #{end}
          AND value IS NOT NULL AND field_id = #{fieldId} AND status = 1
        ORDER BY value + 0 LIMIT 1)      AS `minTime`
FROM iot_collect_data
WHERE uid = #{uid}
  AND field_id = #{fieldId} AND collect_time BETWEEN #{start} AND #{end}
  AND value IS NOT NULL AND status = 1

SELECT id, uid, field, field_id, value, collect_time, status, reason, device_group_Id
FROM iot_collect_data
WHERE uid = #{uid} AND field_id = #{fieldId}
  AND value IS NOT NULL AND status = 1
  AND collect_time BETWEEN #{start} AND #{end}
ORDER BY collect_time

SELECT a.id, a.uid, a.field, a.field_name, a.field_id, a.value, a.collect_time, a.grade, a.indicator
     , a.status, device_name, a.device_group_Id
FROM iot_collect_data a
WHERE a.product_code = #{productCode} AND a.field_id = #{fieldId}
  AND a.collect_time = #{collectTime} AND a.uid != #{excludeUid}
  AND a.value IS NOT NULL AND a.status = 1 and a.grade is not null

SELECT uid, field, field_id, field_name, value, collect_time, grade, indicator,
       device_name, device_sn, device_group_id, puid, cid, status
FROM (
    SELECT uid, field, field_id, field_name, value, collect_time, grade, indicator,
           device_name, device_sn, device_group_id, puid, cid, status,
           ROW_NUMBER() OVER (
               PARTITION BY uid, field_id
               ORDER BY CASE grade WHEN 'fatal' THEN 0 WHEN 'urgent' THEN 1
                        WHEN 'warn' THEN 2 WHEN 'notice' THEN 3
                        WHEN 'normal' THEN 4 WHEN 'status' THEN 5
                        WHEN 'indicator' THEN 6 ELSE 99 END
           ) AS rn
    FROM iot_collect_data
    WHERE collect_time BETWEEN #{startTime} AND #{endTime}
      AND status = 1 AND value IS NOT NULL
      AND uid != #{excludeUid} AND field_id != #{excludeFieldId}
      AND (

                puid = #{puid} OR device_group_id = #{deviceGroupId}


                puid = #{puid}


                device_group_id = #{deviceGroupId}

          )


            AND grade = #{grade}


            AND grade IS NOT NULL


) t WHERE rn = 1
ORDER BY CASE grade WHEN 'fatal' THEN 0 WHEN 'urgent' THEN 1
         WHEN 'warn' THEN 2 WHEN 'notice' THEN 3
         WHEN 'normal' THEN 4 WHEN 'status' THEN 5
         WHEN 'indicator' THEN 6 ELSE 99 END
LIMIT 200

SELECT uid, field, field_id, field_name, value, collect_time, grade, indicator, device_name, device_sn, device_group_id, puid, cid, status FROM ( SELECT uid, field, field_id, field_name, value, collect_time, grade, indicator, device_name, device_sn, device_group_id, puid, cid, status, ROW_NUMBER() OVER ( PARTITION BY uid, field_id ORDER BY CASE grade WHEN 'fatal' THEN 0 WHEN 'urgent' THEN 1 WHEN 'warn' THEN 2 WHEN 'notice' THEN 3 WHEN 'normal' THEN 4 WHEN 'status' THEN 5 WHEN 'indicator' THEN 6 ELSE 99 END ) AS rn FROM iot_collect_data WHERE cid = #{cid} AND status = 1 AND value IS NOT NULL AND uid != #{excludeUid} AND field_id != #{excludeFieldId}
AND grade = #{grade}
AND grade IS NOT NULL
) t WHERE rn = 1 ORDER BY CASE grade WHEN 'fatal' THEN 0 WHEN 'urgent' THEN 1 WHEN 'warn' THEN 2 WHEN 'notice' THEN 3 WHEN 'normal' THEN 4 WHEN 'status' THEN 5 WHEN 'indicator' THEN 6 ELSE 99 END LIMIT 200
